// Pages that changed since the last run. First captures (no baseline yet) and unchanged pages are dropped.
return $input.all()
  .filter(i => i.json.changed === true && i.json.diffImageUrl)
  .map(i => ({ json: { url: i.json.url, device: i.json.device, diffPercent: i.json.diffPercent,
    screenshot: i.json.imageUrl, diff: i.json.diffImageUrl } }));

// One e-mail: a table of changed pages and every diff image attached.
const cfg = $('Configure').first().json;
const pages = $('Changed pages').all().map(i => i.json);
const binary = {};
const names = [];
$input.all().forEach((item, i) => {
  if (!item.binary?.diff) return;
  const host = new URL(pages[i].url).hostname.replace(/[^a-z0-9.-]/gi, '');
  const key = `diff_${i}`;
  binary[key] = { ...item.binary.diff, fileName: `diff-${i + 1}-${host}-${pages[i].device}.png` };
  names.push(key);
});
const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const rows = pages.map(p => `<tr><td><a href="${esc(p.url)}">${esc(p.url)}</a></td><td>${esc(p.device)}</td>` +
  `<td style="text-align:right">${Number(p.diffPercent).toFixed(2)}%</td><td><a href="${esc(p.screenshot)}">screenshot</a></td></tr>`).join('');
const html = `<p>${pages.length} page(s) changed since the last check. Diff images are attached (changed areas in red).</p>` +
  `<table border="1" cellpadding="6" cellspacing="0"><tr><th>Page</th><th>Device</th><th>Changed</th><th></th></tr>${rows}</table>`;
return [{ json: { sendTo: cfg.sendTo, subject: `${pages.length} page(s) changed: ${cfg.monitorName}`, html, attachments: names.join(',') }, binary }];
